// Paste the Slack incoming-webhook URL for the channel these should land in.
// No Slack credential needed - a webhook is all it takes.
const SLACK_WEBHOOK = '';
const e = $input.first().json || {};
const wfName = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || '?';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'no message';
return [{ json: { webhook: SLACK_WEBHOOK, line: `\ud83d\udd34 TN Brain workflow FAILED \u00b7 ${wfName} \u00b7 node: ${node} \u00b7 ${String(msg).slice(0, 300)}` } }];
